from collections import deque
edges = [("H","C"),("C","U"),("U","N"),("H","K"),("K","F"),("F","N"),("H","F")]
adj = {}
for a,b in edges:
    adj.setdefault(a, []).append(b)
dist = {"H": 0}
q = deque(["H"])
while q:
    u = q.popleft()
    for v in adj.get(u, []):
        if v not in dist:
            dist[v] = dist[u] + 1
            q.append(v)
path2 = ["H","C","U","N"]
print(dist["N"])
print(len(path2)-1)
